if (GravDir.IsZero())
{
	return false;
}

// Gravity should be a normalized direction
ensure(GravDir.IsNormalized());

float StepTravelUpHeight = MaxStepHeight;
float StepTravelDownHeight = StepTravelUpHeight;
const float StepSideZ = -1.f * FVector::DotProduct(InHit.ImpactNormal, GravDir);
float PawnInitialFloorBaseZ = OldLocationZ - PawnHalfHeight;
float PawnFloorPointZ = PawnInitialFloorBaseZ;

if (IsMovingOnGround() && CurrentFloor.IsWalkableFloor())
{
	// Since we float a variable amount off the floor, we need to enforce max step height off the actual point of impact with the floor.
	const float FloorDist = FMath::Max(0.f, CurrentFloor.GetDistanceToFloor());
	PawnInitialFloorBaseZ -= FloorDist;
	StepTravelUpHeight = FMath::Max(StepTravelUpHeight - FloorDist, 0.f);
	StepTravelDownHeight = (MaxStepHeight + MAX_FLOOR_DIST*2.f);

	const bool bHitVerticalFace = !IsWithinEdgeTolerance(InHit.Location, InHit.ImpactPoint, PawnRadius);
	if (!CurrentFloor.bLineTrace && !bHitVerticalFace)
	{
		PawnFloorPointZ = CurrentFloor.HitResult.ImpactPoint | -GravDir;
	}
	else
	{
		// Base floor point is the base of the capsule moved down by how far we are hovering over the surface we are hitting.
		PawnFloorPointZ -= CurrentFloor.FloorDist;
	}
}

// Don't step up if the impact is below us, accounting for distance from floor.
if (InitialImpactZ <= PawnInitialFloorBaseZ)
{
	return false;
}

// Scope our movement updates, and do not apply them until all intermediate moves are completed.
FScopedCapsuleMovementUpdate ScopedStepUpMovement(UpdatedComponent, true);

// step up - treat as vertical wall
FHitResult SweepUpHit(1.f);
const FQuat PawnRotation = UpdatedComponent->GetComponentQuat();
MoveUpdatedComponent(-GravDir * StepTravelUpHeight, PawnRotation, true, &SweepUpHit);

if (SweepUpHit.bStartPenetrating)
{
	// Undo movement
	ScopedStepUpMovement.RevertMove();


// Step down
MoveUpdatedComponent(GravDir * StepTravelDownHeight, UpdatedComponent->GetComponentQuat(), true, &Hit);

// If step down was initially penetrating abort the step up
if (Hit.bStartPenetrating)
{
	ScopedStepUpMovement.RevertMove();
	return false;
}

FStepDownResult StepDownResult;
if (Hit.IsValidBlockingHit())
{	
	// See if this step sequence would have allowed us to travel higher than our max step height allows.
	const float DeltaZ = (Hit.ImpactPoint | -GravDir) - PawnFloorPointZ;
	if (DeltaZ > MaxStepHeight)
	{
		//UE_LOGF(LogCharacterMovement, VeryVerbose, "- Reject StepUp (too high Height %.3f) up from floor base %f to %f", DeltaZ, PawnInitialFloorBaseZ, NewLocation.Z);
		ScopedStepUpMovement.RevertMove();
		return false;
	}

	// Reject unwalkable surface normals here.
	if (!IsWalkable(Hit))
	{
		// Reject if normal opposes movement direction
		const bool bNormalTowardsMe = (Delta | Hit.ImpactNormal) < 0.f;
		if (bNormalTowardsMe)
		{
			//UE_LOGF(LogCharacterMovement, VeryVerbose, "- Reject StepUp (unwalkable normal %ls opposed to movement)", *Hit.ImpactNormal.ToString());
			ScopedStepUpMovement.RevertMove();
			return false;
		}

		// Also reject if we would end up being higher than our starting location by stepping down.
		// It's fine to step down onto an unwalkable normal below us, we will just slide off. Rejecting those moves would prevent us from being able to walk off the edge.
		if ((Hit.Location | -GravDir) > OldLocationZ)
		{
			//UE_LOGF(LogCharacterMovement, VeryVerbose, "- Reject StepUp (unwalkable normal %ls above old position)", *Hit.ImpactNormal.ToString());
			ScopedStepUpMovement.RevertMove();
			return false;
		}
	}

	// Reject moves where the downward sweep hit something very close to the edge of the capsule. This maintains consistency with FindFloor as well.
	if (!IsWithinEdgeTolerance(Hit.Location, Hit.ImpactPoint, PawnRadius))
	{
		//UE_LOGF(LogCharacterMovement, VeryVerbose, "- Reject StepUp (outside edge tolerance)");
		ScopedStepUpMovement.RevertMove();
		return false;
	}

	// Don't step up onto invalid surfaces if traveling higher.
	if (DeltaZ > 0.f && !CanStepUp(Hit))
	{
		//UE_LOGF(LogCharacterMovement, VeryVerbose, "- Reject StepUp (up onto surface with !CanStepUp())");
		ScopedStepUpMovement.RevertMove();
		return false;
	}

    }
    let destination = raised + remaining_delta;
    let Some(floor) = floor_sweep_hit(&spatial_query, capsule, radius, destination,
        MAX_STEP_HEIGHT + MAX_FLOOR_DISTANCE * 2.0, &filter, &accepts)
        .filter(|hit| hit.normal1.y >= deg_to_rad(MAX_SLOPE_DEGREES).cos()) else {
        return Some(result);
    };
    if floor.distance == 0.0 && (floor.point1 - floor.point2).dot(floor.normal1) > 0.0 { return Some(result); }
    let next_y = destination.y - floor.distance + clearance;
    if initial_floor_y.is_some_and(|initial| floor.point1.y > initial) && !can_step_up(floor.entity) {
        return Some(result);
    }
    if initial_floor_y.is_some() && find_ground_floor(&spatial_query, destination.with_y(next_y), half, radius,
        cmc, mode, &filter, entity, &candidates).is_none() { return Some(result); }
    if (next_y - center.y).abs() > MAX_STEP_HEIGHT
        || initial_floor_y.is_some_and(|initial| floor.point1.y - initial > MAX_STEP_HEIGHT) {
        return Some(result);
    }
    if initial_floor_y.is_some() && spatial_query.shape_intersections(capsule, destination.with_y(next_y),
        rotation, &filter).into_iter().any(accepts) { return Some(result); }
    if result.1.is_some() { result.1 = Some(remaining_delta); }
    result.2 = Some(next_y);
    Some(result)
}

}
let center = position.0;
let Some((advanced, remaining, next_y)) = grounded_movement_transaction(&spatial_query, capsule,
    center, transform.rotation, half, radius, delta, &params.cmc, *loco, entity, &candidates, &step_permissions) else { continue };
runtime.grounded_move_start = Some(center);
let world_position = next_y.filter(|height| *height > center.y).map_or(advanced, |height| advanced.with_y(height));
transform.translation = parent_world.map_or(world_position, |parent| parent.affine().inverse().transform_point3(world_position));
commands.entity(entity).insert(Position(world_position));
let remaining_velocity = remaining.unwrap_or(delta) / time.delta_secs();
motor.lin.boost.x = remaining_velocity.x - velocity.x;
motor.lin.boost.z = remaining_velocity.z - velocity.z;
motor.lin.acceleration.x = 0.0;
motor.lin.acceleration.z = 0.0;
if next_y.is_none() { continue; }
motor.lin.boost.y = -velocity.y;
motor.lin.acceleration.y = -gravity.value.y;
